style.css:
/* ═══════════════════════════════════════════
   ? PASTEL GOTH TWITCH ?
   dark plum • dusty pink • lavender
   ═══════════════════════════════════════════ */

:root {
    --pg-bg: #120f17 !important;
    --pg-bg-2: #18131f !important;
    --pg-bg-3: #211a2b !important;

    --pg-purple: #b99ae8 !important;
    --pg-purple-dark: #8063a8 !important;

    --pg-pink: #e7a6c7 !important;
    --pg-pink-dark: #a66d8e !important;

    --pg-text: #eee5f3 !important;
    --pg-muted: #b9aebe !important;

    --pg-border: #493953 !important;
    --pg-glow: rgba(185, 154, 232, 0.22) !important;
}

/* ─────────────────────────────────────────
   MAIN PAGE
   ───────────────────────────────────────── */

html,
body {
    background: var(--pg-bg) !important;
    color: var(--pg-text) !important;
}

body {
    background-image:
        radial-gradient(
            circle at 15% 20%,
            rgba(231,166,199,0.06) 0,
            transparent 28%
        ),
        radial-gradient(
            circle at 85% 80%,
            rgba(185,154,232,0.07) 0,
            transparent 30%
        ) !important;
}

/* Main Twitch surfaces */
div[class*="root"],
div[class*="page"],
div[class*="content"],
main {
    background-color: var(--pg-bg) !important;
}

/* ─────────────────────────────────────────
   TOP NAVIGATION
   ───────────────────────────────────────── */

header {
    background: #100d14 !important;
    border-bottom: 1px solid var(--pg-border) !important;
}

nav {
    background: #100d14 !important;
}

/* Search bar */
input[type="search"],
input[placeholder*="Search"] {
    background: var(--pg-bg-3) !important;
    color: var(--pg-text) !important;
    border: 1px solid var(--pg-border) !important;
    border-radius: 10px !important;
}

input[type="search"]:focus,
input[placeholder*="Search"]:focus {
    border-color: var(--pg-pink) !important;
    box-shadow: 0 0 12px var(--pg-glow) !important;
}

/* ─────────────────────────────────────────
   SIDEBAR
   ───────────────────────────────────────── */

aside {
    background: #100d14 !important;
    border-right: 1px solid var(--pg-border) !important;
}

/* Sidebar links */
aside a {
    color: var(--pg-muted) !important;
    transition: 0.2s ease !important;
}

aside a:hover {
    color: var(--pg-pink) !important;
    background: rgba(231,166,199,0.08) !important;
}

/* Live channel cards */
aside [class*="side-nav-card"] {
    border-radius: 8px !important;
}

aside [class*="side-nav-card"]:hover {
    background: rgba(185,154,232,0.08) !important;
}

/* ─────────────────────────────────────────
   LINKS
   ───────────────────────────────────────── */

a {
    color: var(--pg-purple) !important;
}

a:hover {
    color: var(--pg-pink) !important;
}

/* ─────────────────────────────────────────
   BUTTONS
   ───────────────────────────────────────── */

button {
    border-radius: 8px !important;
}

button[data-a-target*="follow"],
button[data-a-target*="subscribe"] {
    background: var(--pg-purple-dark) !important;
    color: #fff !important;
    border: 1px solid var(--pg-purple) !important;
}

button[data-a-target*="follow"]:hover,
button[data-a-target*="subscribe"]:hover {
    background: var(--pg-pink-dark) !important;
    box-shadow: 0 0 15px var(--pg-glow) !important;
}

/* ─────────────────────────────────────────
   VIDEO AREA
   ───────────────────────────────────────── */

video {
    border-radius: 10px !important;
}

/* Video player surrounding area */
[class*="video-player"] {
    background: #0b090d !important;
}

/* ─────────────────────────────────────────
   CHAT
   ───────────────────────────────────────── */

[class*="chat-room"],
[class*="chat-shell"],
[class*="chat-list"] {
    background: #15111b !important;
}

[class*="chat-header"] {
    background: #100d14 !important;
    border-bottom: 1px solid var(--pg-border) !important;
}

/* Chat messages */
[class*="chat-line"] {
    border-radius: 7px !important;
    transition: background 0.15s ease !important;
}

[class*="chat-line"]:hover {
    background: rgba(231,166,199,0.055) !important;
}

/* Chat text */
[class*="chat-line"] span {
    color: var(--pg-text) !important;
}

/* Chat usernames */
[class*="chat-line"] [class*="username"] {
    color: var(--pg-pink) !important;
}

/* Chat input */
textarea,
[class*="chat-input"] textarea {
    background: var(--pg-bg-3) !important;
    color: var(--pg-text) !important;
    border: 1px solid var(--pg-border) !important;
    border-radius: 9px !important;
}

textarea:focus,
[class*="chat-input"] textarea:focus {
    border-color: var(--pg-pink) !important;
    box-shadow: 0 0 12px var(--pg-glow) !important;
}

/* ─────────────────────────────────────────
   CHANNEL INFORMATION
   ───────────────────────────────────────── */

[class*="channel-info"],
[class*="stream-info"] {
    color: var(--pg-text) !important;
}

h1, h2, h3, h4 {
    color: var(--pg-text) !important;
}

/* ─────────────────────────────────────────
   CARDS / BROWSE PAGE
   ───────────────────────────────────────── */

article {
    border-radius: 10px !important;
}

article:hover {
    filter: brightness(1.08) !important;
}

/* Card titles */
[class*="tw-title"],
[class*="title"] {
    color: var(--pg-text) !important;
}

/* ─────────────────────────────────────────
   TAGS
   ───────────────────────────────────────── */

[class*="tag"] {
    background: #2b2034 !important;
    color: var(--pg-pink) !important;
    border: 1px solid #4a3655 !important;
    border-radius: 999px !important;
}

/* ─────────────────────────────────────────
   LIVE INDICATORS
   ───────────────────────────────────────── */

[class*="live"] {
    color: var(--pg-pink) !important;
}

/* ─────────────────────────────────────────
   SCROLLBAR
   ───────────────────────────────────────── */

::-webkit-scrollbar {
    width: 9px !important;
}

::-webkit-scrollbar-track {
    background: #100d14 !important;
}

::-webkit-scrollbar-thumb {
    background: #4a3655 !important;
    border-radius: 10px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--pg-pink-dark) !important;
}

/* ─────────────────────────────────────────
   SELECTION
   ───────────────────────────────────────── */

::selection {
    background: #8063a8 !important;
    color: #fff !important;
}

/* ─────────────────────────────────────────
   SOFT GLOW
   ───────────────────────────────────────── */

button:hover,
a:hover {
    text-shadow: 0 0 8px rgba(231,166,199,0.35) !important;
}

/* ═══════════════════════════════════════════
   END PASTEL GOTH THEME ?
   ═══════════════════════════════════════════ */
